int lengthOfLongestSubstring(string s) {
    unordered_set<char> chars;
    int left = 0, max_len = 0;
    for (int right = 0; right < s.length(); right++) {
        while (chars.count(s[right])) {
            chars.erase(s[left++]);
        }
        chars.insert(s[right]);
        max_len = max(max_len, right - left + 1);
    }
    return max_len;
}

